--- a/src/claims/secondary.rs
+++ b/src/claims/secondary.rs
@@ -18,13 +18,34 @@ pub fn adjudicate(claim: &Claim) -> Decision {
-    let record = external_registry
-        .lookup(claim.coverage.secondary.as_ref())
-        .expect("secondary record must exist");
-    if record.matches_policy(&claim.policy) {
-        Decision::Approve(record.summary())
-    } else {
-        Decision::Deny(record.reason())
-    }
+    let Some(secondary) = claim.coverage.secondary.as_ref() else {
+        return Decision::Approve(primary_summary(claim));
+    };
+
+    // The provider carries no availability commitment: an absent record is a
+    // HOLD, never a denial (interview 2026-09-17, observation 2026-09-19).
+    let record = match external_registry.lookup_bounded(secondary, WAIT_LIMIT) {
+        LookupOutcome::Present(record) => record,
+        LookupOutcome::Absent | LookupOutcome::Timeout => {
+            telemetry::hold(secondary);
+            return Decision::HoldForReview {
+                reason: HoldReason::ExternalRecordUnavailable,
+                evidence: telemetry::last_lookup_trace(),
+            };
+        }
+    };
+
+    if record.matches_policy(&claim.policy) {
+        Decision::Approve(record.summary())
+    } else {
+        Decision::Deny(record.reason())
+    }
